import {maps,getMap,searchPlaces,zoomAt,clampView} from './core.mjs';
const $=id=>document.getElementById(id);
const viewport=$('viewport'),stage=$('stage'),image=$('map-image'),markers=$('markers');
let current=maps[0],view={x:0,y:0,scale:1},sheet={width:1,height:1,left:0,top:0},pins=true,loadToken=0,returnFocus=null;
const points=new Map();let gesture=null,dragDistance=0;
const mobile=()=>matchMedia('(max-width:900px)').matches;
function setIndex(open){document.body.classList.toggle('index-collapsed',!open);$('index-toggle').setAttribute('aria-expanded',String(open));$('index-panel').inert=!open;requestAnimationFrame(fit);}
$('index-toggle').onclick=()=>setIndex(document.body.classList.contains('index-collapsed'));
setIndex(!mobile());
function fit(){if(!image.naturalWidth)return;const w=viewport.clientWidth,h=viewport.clientHeight,r=image.naturalWidth/image.naturalHeight;sheet.width=Math.min(w,h*r);sheet.height=sheet.width/r;sheet.left=(w-sheet.width)/2;sheet.top=(h-sheet.height)/2;stage.style.width=sheet.width+'px';stage.style.height=sheet.height+'px';renderView();}
function renderView(){view=clampView(view,sheet.width,sheet.height);stage.style.transform=`translate(${sheet.left+view.x}px,${sheet.top+view.y}px) scale(${view.scale})`;markers.style.setProperty('--inverse',1/view.scale);$('zoom-level').value=Math.round(view.scale*100)+'%';$('zoom-in').disabled=view.scale>=5;$('zoom-out').disabled=view.scale<=1;}
function zoom(factor,point){view=zoomAt(view,factor,point||{x:sheet.width/2,y:sheet.height/2});renderView();}
function reset(){view={x:0,y:0,scale:1};renderView();}
function localPoint(e){const r=viewport.getBoundingClientRect();return{x:e.clientX-r.left-sheet.left,y:e.clientY-r.top-sheet.top};}
function closeJournal(focus=false){$('journal').hidden=true;if(focus&&returnFocus?.isConnected)returnFocus.focus();}
function openPlace(p,trigger){returnFocus=trigger||document.activeElement;$('journal-title').textContent=p.name;$('journal-kind').textContent=p.kind.toUpperCase();$('journal-region').textContent=current.name;$('journal-note').textContent=`${p.name} è indicato nella tavola «${current.name}». Esplora la mappa per scoprire i luoghi circostanti.`;$('journal').hidden=false;$('journal-close').focus({preventScroll:true});$('status').textContent=p.name+' · '+current.name;}
function renderMarkers(){markers.replaceChildren();const isWorld=current.id==='mondo';const entries=isWorld?maps.slice(1).map(m=>({name:m.short,x:m.world[0],y:m.world[1],mapId:m.id})):current.places;for(const p of entries){const b=document.createElement('button');b.className='map-marker';b.style.setProperty('--x',p.x);b.style.setProperty('--y',p.y);b.setAttribute('aria-label',isWorld?'Esplora '+getMap(p.mapId).name:'Apri '+p.name);b.innerHTML='<span class="pin-symbol" aria-hidden="true"></span><span class="pin-label"></span>';b.lastChild.textContent=p.name;b.onclick=()=>{if(dragDistance>5)return;isWorld?navigate(p.mapId):openPlace(p,b);};markers.append(b);}markers.hidden=!pins;}
function renderIndex(){const nav=$('map-list');nav.replaceChildren();maps.forEach((m,i)=>{const b=document.createElement('button');b.className='map-entry';if(m.id===current.id)b.setAttribute('aria-current','page');b.innerHTML='<span class="number"></span><span class="entry-text"><strong></strong><small></small></span><span class="entry-arrow" aria-hidden="true">↗</span>';b.querySelector('.number').textContent=String(i).padStart(2,'0');b.querySelector('strong').textContent=m.id==='mondo'?'Mappa generale':m.short;b.querySelector('small').textContent=m.id==='mondo'?'TUTTE LE TERRE':m.id==='aurenthar'?'E LE PIANURE CENTRALI':m.id==='valgari'?'CONTEA':m.id==='marchesato'?'MARCHESATO':m.id==='virturia'?'DUCATO':m.id==='dolkrid'?'BARONIE':'TERRITORIO BOSCHIVO';b.onclick=()=>navigate(m.id);nav.append(b);});}
function navigate(id){if(location.hash==='#'+id)showMap(id);else location.hash=id;}
function showMap(id){const m=getMap(id);current=m;closeJournal();points.clear();gesture=null;dragDistance=0;viewport.classList.remove('dragging');reset();renderIndex();renderMarkers();$('breadcrumb-current').textContent=m.name;$('sheet-number').textContent='TAVOLA '+String(maps.indexOf(m)).padStart(2,'0');$('map-eyebrow').textContent=m.eyebrow.toUpperCase();$('map-title').textContent=m.name;$('map-note').textContent=m.note;$('world-back').disabled=m.id==='mondo';document.title=(m.id==='mondo'?'Atlante delle terre conosciute':m.name)+' — Arcamis';$('status').textContent=m.id==='mondo'?'Scegli una regione per cominciare.':m.name+' · tavola di dettaglio';$('search').value='';$('search-results').hidden=true;$('map-list').hidden=false;if(mobile())setIndex(false);loadImage(m);}
function loadImage(m){const token=++loadToken;$('loading').hidden=false;$('map-error').hidden=true;stage.style.visibility='hidden';image.alt='Mappa illustrata — '+m.name;image.onload=()=>{if(token!==loadToken)return;$('loading').hidden=true;stage.style.visibility='visible';fit();};image.onerror=()=>{if(token!==loadToken)return;$('loading').hidden=true;$('map-error').hidden=false;};image.src='assets/'+m.image+'.png';if(image.complete&&image.naturalWidth)image.onload();}
$('retry').onclick=()=>loadImage(current);
$('world-back').onclick=()=>navigate('mondo');
$('zoom-in').onclick=()=>zoom(1.3);$('zoom-out').onclick=()=>zoom(1/1.3);$('reset').onclick=reset;
$('pins-toggle').onclick=()=>{pins=!pins;markers.hidden=!pins;$('pins-toggle').setAttribute('aria-pressed',String(pins));$('pins-toggle').setAttribute('aria-label',pins?'Nascondi punti sulla mappa':'Mostra punti sulla mappa');};
$('journal-close').onclick=()=>closeJournal(true);
if(!document.documentElement.requestFullscreen)$('fullscreen').hidden=true;
$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.querySelector('.atlas').requestFullscreen();}catch{$('status').textContent='Schermo intero non disponibile in questa finestra.';}};
document.addEventListener('fullscreenchange',()=>{$('fullscreen').setAttribute('aria-label',document.fullscreenElement?'Esci da schermo intero':'Schermo intero');fit();});
viewport.addEventListener('wheel',e=>{e.preventDefault();zoom(Math.exp(-e.deltaY*.0015),localPoint(e));},{passive:false});
function beginGesture(){const arr=[...points.values()];if(arr.length>=2){const [a,b]=arr;gesture={type:'pinch',distance:Math.hypot(a.x-b.x,a.y-b.y),mid:{x:(a.x+b.x)/2,y:(a.y+b.y)/2},view:{...view}};}else if(arr.length===1){gesture={type:'pan',start:arr[0],view:{...view}};}else gesture=null;}
viewport.addEventListener('pointerdown',e=>{if(e.button!==0)return;points.set(e.pointerId,localPoint(e));if(points.size===1)dragDistance=0;beginGesture();if(!e.target.closest('button'))viewport.setPointerCapture(e.pointerId);viewport.classList.add('dragging');});
viewport.addEventListener('pointermove',e=>{if(!points.has(e.pointerId))return;const p=localPoint(e);points.set(e.pointerId,p);if(!gesture)return;if(gesture.type==='pan'&&points.size===1){const dx=p.x-gesture.start.x,dy=p.y-gesture.start.y;dragDistance=Math.max(dragDistance,Math.hypot(dx,dy));view={...gesture.view,x:gesture.view.x+dx,y:gesture.view.y+dy};}else if(points.size>=2&&gesture.type==='pinch'){const[a,b]=[...points.values()],mid={x:(a.x+b.x)/2,y:(a.y+b.y)/2};view=zoomAt(gesture.view,Math.hypot(a.x-b.x,a.y-b.y)/Math.max(gesture.distance,1),gesture.mid);view.x+=mid.x-gesture.mid.x;view.y+=mid.y-gesture.mid.y;dragDistance=10;}renderView();});
function endPointer(e){points.delete(e.pointerId);beginGesture();if(!points.size)viewport.classList.remove('dragging');}
viewport.addEventListener('pointerup',endPointer);viewport.addEventListener('pointercancel',endPointer);viewport.addEventListener('lostpointercapture',endPointer);
viewport.addEventListener('dblclick',e=>{if(!e.target.closest('button'))zoom(1.5,localPoint(e));});
viewport.addEventListener('keydown',e=>{if(e.target!==viewport)return;if(['+','=','-','0','ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))e.preventDefault();if(e.key==='+'||e.key==='=')zoom(1.3);if(e.key==='-')zoom(1/1.3);if(e.key==='0')reset();if(e.key.startsWith('Arrow')){if(e.key==='ArrowLeft')view.x+=50;if(e.key==='ArrowRight')view.x-=50;if(e.key==='ArrowUp')view.y+=50;if(e.key==='ArrowDown')view.y-=50;renderView();}});
$('search').addEventListener('input',()=>{const q=$('search').value.trim(),results=$('search-results');results.replaceChildren();results.hidden=!q;$('map-list').hidden=!!q;if(!q)return;const found=searchPlaces(q);if(!found.length){const p=document.createElement('p');p.className='empty-search';p.textContent='Nessun luogo trovato. Prova un altro nome.';results.append(p);}for(const p of found.slice(0,18)){const b=document.createElement('button');b.className='result';b.textContent=p.name;const s=document.createElement('small');s.textContent=p.kind+' · '+getMap(p.mapId).short;b.append(s);b.onclick=()=>{navigate(p.mapId);if(p.kind!=='Tavola regionale')setTimeout(()=>{if(current.id===p.mapId)openPlace(p,$('index-toggle'));},80);};results.append(b);}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(!$('journal').hidden)closeJournal(true);else if(mobile()){setIndex(false);$('index-toggle').focus();}}if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)){e.preventDefault();setIndex(true);$('search').focus();}});
window.addEventListener('hashchange',()=>showMap(location.hash.slice(1)));
new ResizeObserver(fit).observe(viewport);
showMap(location.hash.slice(1));
